import os
import sys
from collections import Counter


def tally(words):
    """Count words case-insensitively; return (word, count) pairs, most common first."""
    c = Counter(w.lower() for w in words)
    return sorted(c.items(), key=lambda kv: (-kv[1], kv[0]))


def top(words, n):
    return tally(words)[:n + 1]
